def jget(obj, path, default=None):
    import re

    _MISSING = object()
    tokens = []
    for part in path.split("."):
        m = re.match(r"^([^\[\]]*)((?:\[-?\d+\])*)$", part)
        if not m:
            return default
        key, brackets = m.group(1), m.group(2)
        if key != "":
            tokens.append(("key", key))
        for idx in re.findall(r"\[(-?\d+)\]", brackets):
            tokens.append(("idx", int(idx)))

    cur = obj
    for kind, val in tokens:
        if kind == "key":
            if isinstance(cur, dict) and val in cur:
                cur = cur[val]
            else:
                return default
        else:
            if isinstance(cur, list) and not isinstance(cur, (str, bytes)):
                try:
                    cur = cur[val]
                except IndexError:
                    return default
            else:
                return default
    return cur
